import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl,
    sinusoidal modulation, and pairwise interactions to approximate
    target ELA features.

    Formula: f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + interactions(x) + skew_term(x)

    Components:
    - quadratic_bowl: Creates a simple quadratic bowl landscape.
    - sinusoidal_modulation: Adds oscillations to the landscape.
    - interactions: Introduces pairwise interactions between dimensions.
    - skew_term: Skews the distribution of fitness values.
    """
    def quadratic_bowl(x):
        return np.sum(x**2)

    def sinusoidal_modulation(x):
        return np.sum(np.sin(2 * x))

    def interactions(x):
        interaction_strength = 0.1
        interaction_sum = 0
        for i in range(len(x)):
            for j in range(i + 1, len(x)):
                interaction_sum += x[i] * x[j]
        return interaction_strength * interaction_sum

    def skew_term(x):
        skew_factor = 0.5
        return skew_factor * np.max(x)

    return quadratic_bowl(x) + sinusoidal_modulation(x) + interactions(x) + skew_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a cubic bowl with sinusoidal modulation, a linear term, and pairwise interactions to achieve target ELA properties.

    Formula:
    f(x) = sum(x_i^3) + 0.5 * sum(sin(2*x_i)) + 0.2 * sum(x_i) + 0.1 * sum(x_i * x_j for all i<j)
    """
    val = np.sum(x**3) + 0.5 * np.sum(np.sin(2*x)) + 0.2 * np.sum(x)

    # Add pairwise interactions
    for i in range(len(x)):
        for j in range(i + 1, len(x)):
            val += 0.1 * x[i] * x[j]
    return float(val)
